/*
 * A105392  Frobenius number of the subsemigroup of the natural numbers
 *          generated by successive pairs of Lucas numbers.
 * https://oeis.org/A105392
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = (L(n)-1)*(L(n+1)-1)-1 where L(n) = A000204(n)
 * Range:     u8 n <= 5, u16 n <= 11, u32 n <= 22, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Compute by iterating the Lucas sequence */

seq_t a(idx_t n)
{
    /* a(1) is conventionally 0; the formula holds for n ≥ 2 */
    if (n <= 1)
        return 0;

    /* Lucas numbers: L(0)=2, L(1)=1 */
    seq_t l_prev = 2;  /* L(0) */
    seq_t l_curr = 1;  /* L(1) */

    /* compute up to L(n+1) */
    for (idx_t i = 2; i <= n + 1; ++i)
    {
        seq_t temp = l_prev + l_curr;
        l_prev = l_curr;
        l_curr = temp;
    }

    /* Now l_prev = L(n), l_curr = L(n+1) */
    seq_t term1 = l_prev - 1;
    seq_t term2 = l_curr - 1;
    seq_t prod  = term1 * term2;
    return prod - 1;
}
